Here's a C++ function that converts markdown to HTML, taking a reference to a std::string containing markdown text and returning a std::string with the corresponding HTML text:

    ```cpp
    #include <iostream>
    #include <string>
    #include <regex>

    std::string markdown_to_html(const std::string& markdown) {
        // Create a map to store markdown syntax replacements
        const std::map<std::string, std::string> markup_replacements = {
            {"# ", "<h1>"},   // Header 1
            {"## ", "<h2>"},  // Header 2
            {"### ", "<h3>"}, // Header 3
            {"#### ", "<h4>"},// Header 4
            {"##### ", "<h5>"},// Header 5
            {"###### ", "<h6>"},// Header 6
            {">`", "<pre><code>"}, // Code block (begin)
            {"`", "</code></pre>"} // Code block (end)
        };

        // Loop through each markup replacement and perform the substitution
        std::stringstream html;
        for (const auto& entry : markup_replacements) {
            std::regex syntax(entry.first);
            html << std::regex_replace(markdown, syntax, entry.second);
        }

        // Handle other markdown syntax not handled by the map
        html << std::regex_replace(markdown, std::regex("\\*(.*?)\\*"),
            "$1") << std::regex_replace(markdown, std::regex("_(.*?)_"), "$1"); // Emphasis

        // Convert links to HTML links
        html << std::regex_replace(markdown, std::regex("\\[(.*?)\\]\\((.*?)\\)"),
            "<a href=\"\\2\">\\1</a>");

        // Convert images to HTML images
        html << std::regex_replace(markdown, std::regex("!\\[(.*?)\\]\\((.*?)\\)"),
            "<img src=\"\\2\" alt=\"\\1\">");

        return html.str();
    }

    // Example usage:
    int main() {
        std::string markdown = "## Markdown to HTML Converter\n\nThis function converts markdown text to HTML.\n\n> Markdown is a lightweight formatting syntax for text.\n\nThe following list is in markdown format:\n\n1. Item 1\n2. Item 2\n3. Item 3";
        std::string html = markdown_to_html(markdown);
        std::cout << "Markdown input:\n" << markdown << "\n\nHTML output:\n" << html << std::endl;
        return 0;
    }
    ```
